import axios from "axios";
import { useEffect } from "react";

function Home() {

  useEffect(() => {
    axios.get("http://localhost:5000")
      .then(res => console.log(res.data))
      .catch(err => console.log(err));
  }, []);

  return (
    <div>
      <h1>MediReminder</h1>
    </div>
  );
}

export default Home;
